    "sourceHash": "sha256:e1d090fb823c52571b813ad96de6773ace0f269389b9456210d00fb334c0ae3b",
    "translatableHash": "sha256:cab44aee791a34daf7b1e0c7bc3c9a345d30d3753cfa02da2b37b799fbbd006d",
    "data": {
      "schemaVersion": 1,
      "name": "Blighted Speaker in Spores",
      "level": 13,
      "rarity": "rare",
      "size": "large",
      "traits": [
        "fungus",
        "mutant"
      ],
      "description": "As Zibik wanders the blighted wilderness and takes on the toxins of others, his body is overburdened by fungal growths. Zibik sheds these growths during his cycle of death and rebirth, and they sometimes emerge as a fungal creature that's independent of but innately connected to the green man. Zibik often shapes a speaker in spores to resemble an animal he encountered recently; speakers very rarely share the same form, but they all appear like fungal growths surrounded by glowing spores.",
      "armorClass": 32,
      "hitPoints": 250,
      "speedFeet": 40,
      "perception": {
        "modifier": 25,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 23,
        "reflex": 20,
        "will": 27
      },
      "abilities": {
        "str": 7,
        "dex": 3,
        "con": 4,
        "int": -2,
        "wis": 8,
        "cha": 2
      },
      "skills": {
        "acrobatics": 22,
        "athletics": 24,
        "intimidation": 21,
        "nature": 27,
        "survival": 27
      },
      "languages": [
        "muan",
        "wildsong"
      ],
      "defenses": {
        "immunities": [
          "poison"
        ],
        "resistances": [
          "bludgeoning 15",
          "piercing 15"
        ],
        "weaknesses": [
          "fire 15",
          "slashing 15"
        ]
      },
      "attacks": [
        {
          "id": "KbLid1hjvgm6vzDC",
          "name": "Tendril",
          "bonus": 28,
          "damage": "1d6 poison; 3d10+13 bludgeoning",
          "traits": [
            "reach-10"
          ]
        }
      ],
      "actions": [
        {
          "id": "fm8f64IkYgzjeS8q",
          "name": "Shaped Tongue",
          "kind": "passive",
          "description": "The speaker in spores can speak with all plants and the creature they resemble.",
          "traits": []
        },
        {
          "id": "ydYe3xCq5mKtBnWK",
          "name": "Spore Matrix",
          "kind": "passive",
          "description": "60 feet.\nThe speaker in spores is surrounded by a strong concentration of spores. The speaker can communicate telepathically to any creatures in the aura who have breathed in their spores. This communication always uses the listener's native language and can't be used with a creature that doesn't breathe.",
          "traits": [
            "aura",
            "mental",
            "primal"
          ]
        },
        {
          "id": "9lZkGsGN1jC2gr1X",
          "name": "Sporesight (Imprecise) 120 feet",
          "kind": "passive",
          "description": "The speaker in spores can see through spores drifting in the air, ignoring cover. This is an imprecise sense and functions only in areas without strong wind currents. Sporesight doesn't function underwater.",
          "traits": []
        },
        {
          "id": "uXvgtood7GBTpaxH",
          "name": "Constant Spells",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "5bh50PFBvi5JE12E",
          "name": "Blight Walker",
          "kind": "passive",
          "description": "The speaker in spores recovers from the Paralyzed, Slowed, and Stunned conditions at the end of their turn. They're also immune to penalties to their Speeds and ignore cover, concealment, difficult terrain, and greater difficult terrain resulting from plants or fungi.",
          "traits": []
        },
        {
          "id": "ZjKCneopRcXQbI3U",
          "name": "Toxic Spores",
          "kind": "reaction",
          "description": "Trigger A creature critically hits the speaker or the speaker dies\nEffect The blighted speaker in spores releases a burst of toxic spores. Any creature within 10 feet of the speaker in spores takes 3d6 poison damage (check (fortitude, dc:31, basic) save). Creatures that fail their saving throw are exposed to Ayrzul's Blight.",
          "traits": []
        },
        {
          "id": "tTRerHiQUoyqeDxy",
          "name": "Accelerate Decay",
          "kind": "action",
          "description": "The speaker in spores unleashes void energy that forces desiccation in a 30-foot emanation. Each living creature in the area takes 14d6 void damage (check (fortitude, dc:33, basic, options:area-effect) save). Creatures afflicted by a disease take a –2 circumstance penalty to this save.\nAll Small or smaller non-magical plant life (though not plant creatures) in the area wither and die, eliminating any cover or concealment and leaving difficult terrain in their wake.\nThe speaker in spores is immune to this effect and can't use this ability again for 1d4.",
          "traits": [
            "primal",
            "void"
          ]
        },
        {
          "id": "Ir3VJ4WcvWlwr8CA",
          "name": "Ayrzul's Blight",
          "kind": "passive",
          "description": "Radioactive elemental energy courses through sap and blood, petrifies bark and bone, withers flesh, and mutates life. Creatures with the wood or plant trait treat critical successes against the disease as successes. The drained condition caused by Ayrzul's Blight can't be healed until the disease is removed. Ayrzul's Blight presents with obvious but varying symptoms, from coughing up black dust to suddenly becoming covered in itchy patches of flaky stone.\nSaving Throw check (fortitude, dc:33)\nOnset 1 day\nStage 1 Drained 1 (1 day)\nStage 2 Drained 2 (1 day)\nStage 3 Drained 3 (1 day)\nStage 4 Drained 4 (1 day)\nStage 5 mutation (on a failure) or death (on a critical failure)",
          "traits": [
            "disease",
            "earth",
            "primal"
          ]
        }
      ],
      "spellcasting": [
        {
          "id": "e4DbBURvhF8eraFQ",
          "name": "Primal Innate Spells",
          "tradition": "primal",
          "category": "innate",
          "attackModifier": 25,
          "saveDc": 33,
          "spells": [
            {
              "id": "04uAZlPqfY2Ccmuv",
              "name": "Environmental Endurance (Constant)",
              "rank": 5
            },
            {
              "id": "go9ACYAZS1cIOqsc",
              "name": "Fly (Constant)",
              "rank": 5
            }
          ]
        }
      ]
    }
