    "translatableHash": "sha256:acebceb61b63a2fecdc37d42384972d352a7f0838e1b10813322f8d489e3ad8b",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Blood Drain",
      "level": 6,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "A tiny spark of Nin's will drains the blood from living intruders.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 15,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:26) (expert) to vandalize the space, or check (religion, dc:24) (expert) to pray to a god for passage, or Dispel Magic (3rd rank; counteract DC 25) to counteract the magical energy",
      "isComplex": true,
      "routine": "(1 action) On its initiative, the trap continues to drain blood, dealing 2d6+8 void damage to all living creatures in the room (check (fortitude, dc:26, basic) save). On a failure, a creature increases the value of their drained condition by 1.",
      "reset": "The trap automatically deactivates after 1 minute. It resets in 1 hour.",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "vM6DtwCWDbtOEaYw",
          "name": "Drain Blood",
          "kind": "reaction",
          "description": "Trigger A living creature enters the room of their own accord\nEffect The trap drains the blood from all living creatures in the room, which manifests as a bloody mist in the air. All living creatures in the room are dealt 2d6+8 void damage (check (fortitude, dc:26, basic) save). On a failure, a creature increases the value of their drained condition by 1. The trap then rolls initiative.",
          "traits": [
            "divine",
            "void"
          ]
        }
      ]
    }
