    "data": {
      "schemaVersion": 1,
      "name": "Riptide Octopus Swarm",
      "level": 0,
      "rarity": "common",
      "size": "large",
      "traits": [
        "animal",
        "aquatic",
        "swarm"
      ],
      "description": "Riptide octopuses have adapted to these isolated hunting grounds with their strength, pulling themselves hundreds of feet across dry land to check their territory's pools for prey. Under most circumstances, such mollusks are solitary. However, massive scavenging opportunities like a beached whale or a wounded mammal can draw hundreds of these creatures to one place.\nEater of Toes\nThe riptide octopus didn't get its name from living in tidal zones but from being more stubborn than a riptide pulling someone out to sea. Beachcombers know not to dip their toes into tidal pools lest a riptide octopus mistake them for prey, and many bear scars that remind them of the dangers of ignoring such advice. Dislodging a hungry riptide octopus sometimes takes extreme measures in the form of a crowbar; fortunately, the octopus's skin is sensitive to fermented fluids like vinegar and wine, and dousing the creature with such concoctions usually encourages it to detach and flee.",
      "armorClass": 16,
      "hitPoints": 14,
      "speedFeet": 15,
      "perception": {
        "modifier": 6,
        "senses": [
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 8,
        "reflex": 7,
        "will": 4
      },
      "abilities": {
        "str": 2,
        "dex": 3,
        "con": 3,
        "int": -4,
        "wis": 3,
        "cha": 0
      },
      "skills": {
        "acrobatics": 6,
        "athletics": 5,
        "stealth": 6,
        "thievery": 4
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "precision",
          "swarm-mind"
        ],
        "resistances": [
          "physical 5 except slashing"
        ],
        "weaknesses": [
          "area-damage 3",
          "splash-damage 3"
        ]
      },
      "attacks": [],
      "actions": [
        {
          "id": "pV5jZwvRYcpE7toP",
          "name": "Camouflage",
          "kind": "passive",
          "description": "In wet environments like open water, tide pools, and even wet ship decks, a riptide octopus swarm can Hide and Sneak without cover or being Concealed.",
          "traits": []
        },
        {
          "id": "qkrFgGUiwzSNSuha",
          "name": "Compression",
          "kind": "passive",
          "description": "A riptide octopus swarm can move through a gap at least 6 inches wide without Squeezing and can Squeeze through a gap at least 1 inch wide.",
          "traits": []
        },
        {
          "id": "Otyyh8UUQ4IZBbwU",
          "name": "Swarming Bites",
          "kind": "action",
          "description": "Each enemy in the swarm's space takes 1d4 piercing damage and must attempt a check (reflex, dc:16, basic, options:area-effect) save. A creature that fails its save takes 1d4 persistent piercing damage as octopuses cling to and continue biting the creature.",
          "traits": []
        }
      ],
      "spellcasting": []
    }
